async function readImageSource(file:File){return new Promise<string>((resolve,reject)=>{if(!file.type.startsWith('image/')){reject(new Error('image'));return}const reader=new FileReader();reader.onerror=()=>reject(reader.error);reader.onload=()=>resolve(String(reader.result));reader.readAsDataURL(file)})}
async function cropAvatar(source:string,scale:number,offsetX:number,offsetY:number){return new Promise<string>((resolve,reject)=>{const img=new Image();img.onload=()=>{const size=640;const canvas=document.createElement('canvas');canvas.width=size;canvas.height=size;const ctx=canvas.getContext('2d');if(!ctx){reject(new Error('canvas'));return}ctx.fillStyle='#eef2f7';ctx.fillRect(0,0,size,size);const base=Math.max(size/img.width,size/img.height);const drawW=img.width*base*scale;const drawH=img.height*base*scale;const x=(size-drawW)/2+(offsetX/100)*size;const y=(size-drawH)/2+(offsetY/100)*size;ctx.save();ctx.beginPath();ctx.arc(size/2,size/2,size/2,0,Math.PI*2);ctx.clip();ctx.drawImage(img,x,y,drawW,drawH);ctx.restore();resolve(canvas.toDataURL('image/jpeg',.88))};img.onerror=()=>reject(new Error('image'));img.src=source})}

