 const save=async()=>{if(!directoryConfigured){setError('Каталог аккаунтов не настроен. Проверьте адрес WorkerTink Directory.');return}if(!draft.name.trim()){setError('Укажите имя');return}if(!draft.position.trim()){setError('Укажите должность');return}if(!/^\d{6}$/.test(pin)){setError('PIN должен состоять ровно из 6 цифр');return}if(pin!==pinRepeat){setError('PIN-коды не совпадают');return}setBusy(true);try{let profile={...draft,name:draft.name.trim(),position:draft.position.trim(),profileId:normalizeWTinkId(draft.profileId)||createWTinkId()};let result:Awaited<ReturnType<typeof registerProfile>>|undefined;for(let attempt=0;attempt<3;attempt++){try{result=await registerProfile(profile,pin);break}catch(error){if(!String(error).includes('WTINK_ID_TAKEN')||attempt===2)throw error;profile={...profile,profileId:createWTinkId()}}}if(!result)throw new Error('REGISTER_FAILED');setState(s=>({...s,profile:{...result!.profile,profileId:normalizeWTinkId(result!.profile.profileId)||result!.profile.profileId},directoryToken:result!.token,onePassEnabled:false,setupComplete:false}));}catch(error){const code=String(error);setError(code.includes('WTINK_ID_TAKEN')?'Не удалось подобрать свободный WTinkID.':code.includes('INVALID_PIN')?'PIN должен состоять из 6 цифр':'Не удалось создать аккаунт. Проверьте соединение с каталогом.')}finally{setBusy(false)}};
