function ChatBubble({message,own,onActivate,onApplyNote}:{message:ChatMessage;own:boolean;onActivate:(p:UserProfile)=>void;onApplyNote:(n:{date:string;note:string})=>void}){
 const profile=message.type==='profile'?message.profile:undefined;
 const note=message.type==='note'?message.note:undefined;
 return <div className={`chat-row ${own?'own':''}`}><div className="chat-bubble">{message.type==='text'&&<p>{message.text}</p>}{profile&&<div className="share-card"><div className="share-title"><Avatar profile={profile} size="sm"/><div><b>Профиль</b><span>{profile.name}</span></div></div><p>{profile.position||'Должность не указана'}</p><Button primary onClick={()=>onActivate(profile)}>Активировать профиль</Button></div>}{note&&<div className="share-card"><div className="share-title"><span className="share-icon">✎</span><div><b>Заметка смены</b><span>{note.date} · {note.shift||'смена'}</span></div></div><div className="note-preview">{note.note.slice(0,260)}</div><Button primary onClick={()=>onApplyNote(note)}>Активировать на {note.date}</Button></div>}<time>{new Date(message.at).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</time></div></div>}

function PairingModal({mode,signal,answer,status,setSignal,setAnswer,onCreate,onAccept,onApply,onClose}:{mode:'create'|'join';signal:string;answer:string;status:string;setSignal:(s:string)=>void;setAnswer:(s:string)=>void;onCreate:()=>void;onAccept:()=>void;onApply:()=>void;onClose:()=>void}){return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><section className="pair-modal" role="dialog" aria-modal="true" aria-labelledby="pair-title"><header className="modal-head"><div><span className="eyebrow">Резервное подключение</span><h2 id="pair-title">Подключить P2P</h2><p>Поиск и заявки работают через WTinkID. Этот экран нужен только как резервный способ вручную установить прямой WebRTC-канал.</p></div><button className="modal-close" onClick={onClose}>×</button></header><div className="pair-tabs"><button className={mode==='create'?'active':''} onClick={onCreate}>Создать технический код</button><button className={mode==='join'?'active':''} onClick={()=>{setSignal('');setAnswer('')}}>Ввести код коллеги</button></div>{mode==='create'?<><Field label="Технический код"><textarea readOnly value={signal} placeholder="Создайте технический код…"/></Field><div className="pair-actions"><Button primary onClick={onCreate}>Создать код</Button><Button quiet onClick={()=>{if(signal)navigator.clipboard?.writeText(signal)}} disabled={!signal}>Копировать</Button></div><Field label="Ответ коллеги" help="Коллега должен вставить код у себя, создать ответ и прислать его обратно."><textarea value={answer} onChange={e=>setAnswer(e.target.value)} placeholder="Вставьте ответ сюда…"/></Field><Button primary onClick={onApply} disabled={!answer}>Подключиться</Button></>:<><Field label="Технический код"><textarea value={signal} onChange={e=>setSignal(e.target.value)} placeholder="Вставьте технический код коллеги…"/></Field><div className="pair-actions"><Button primary onClick={onAccept} disabled={!signal}>Создать ответ</Button><Button quiet onClick={()=>{if(answer)navigator.clipboard?.writeText(answer)}} disabled={!answer}>Копировать ответ</Button></div><Field label="Ваш ответ"><textarea readOnly value={answer} placeholder="Ответ появится здесь…"/></Field></>}{status&&<div className="pair-status">{status}</div>}<p className="pair-foot">Для соединения через интернет используется STUN для обнаружения маршрута. Сам чат передаётся по прямому WebRTC-каналу.</p></section></div>}

function CalendarView({state,view,days,calc,shiftMonth,onPay,onAbsence,onEdit}:{state:State;view:Date;days:(Date|null)[];calc:ReturnType<typeof calcMonth>;shiftMonth:(n:number)=>void;onPay:()=>void;onAbsence:()=>void;onEdit:(date:string)=>void}){return <section className="calendar-layout"><div className="month-card"><div className="month-head"><div><span className="eyebrow">{state.scheduleType} · {state.scheduleType==='2/2'?(state.schedulePairType==='day-night'?'день / ночь':state.schedulePairType==='day-day'?'день / день':'ночь / ночь'):state.scheduleShift==='day'?'дневные':state.scheduleShift==='night'?'ночные':'сутки'}</span><h2>{MONTHS[view.getMonth()]} <em>{view.getFullYear()}</em></h2></div><div className="month-controls"><button onClick={()=>shiftMonth(-1)} aria-label="Предыдущий месяц">‹</button><button onClick={()=>shiftMonth(1)} aria-label="Следующий месяц">›</button></div></div><div className="calendar"><div className="calendar-week">{DOW.map(d=><span key={d}>{d}</span>)}</div><div className="calendar-grid">{days.map((d,i)=>d?<CalendarDay key={i} state={state} date={d} onEdit={onEdit}/>:<div className="empty-day" key={i}/>)}</div></div><div className="calendar-note"><span>Нажмите на день, чтобы изменить смену и открыть заметку</span><span><b>П</b> — праздник · синяя рамка — сегодня</span></div></div><aside className="summary-stack"><div className="balance-card"><span>На руки за месяц</span><strong>{formatMoney(calc.net)}</strong><small>{MONTHS[view.getMonth()].toLowerCase()}</small><div className="balance-rule"><i style={{width:`${calc.gross?Math.min(100,Math.max(8,calc.net/calc.gross*100)):8}%`}}/></div><small>Начислено {formatMoney(calc.gross)} · НДФЛ {formatMoney(calc.tax)}</small></div><div className="stat-card"><div><b>{calc.work}</b><span>смен</span></div><div><b>{calc.holidayWork}</b><span>праздничных</span></div><div><b>{calc.vacDays}</b><span>отпуск</span></div><div><b>{calc.sickDays}</b><span>больничный</span></div></div><div className="quick-actions"><button onClick={onPay}><span className="quick-icon"><Icon name="pay"/></span><span><b>Зарплата и выплаты</b><small>Аванс · остаток · даты</small></span><i>›</i></button><button onClick={onAbsence}><span className="quick-icon"><Icon name="absence"/></span><span><b>Отпуск и больничные</b><small>Добавить или изменить период</small></span><i>›</i></button></div><div className="legend-card"><span><i className="dot day"/>День</span><span><i className="dot night"/>Ночь</span><span><i className="dot full"/>Сутки</span><span><i className="dot off"/>Выходной</span><span><i className="dot holiday"/>Праздник</span></div></aside></section>}
function CalendarDay({state,date,onEdit}:{state:State;date:Date;onEdit:(date:string)=>void}){const dateKey=ymd(date),beforeStart=state.startDate?dateKey<state.startDate:false,today=ymd(new Date())===dateKey,holiday=isHoliday(date),note=Boolean(state.shiftNotes[dateKey]?.trim());if(beforeStart)return <button className={`calendar-day pre-start ${today?'today':''}`} disabled title="До даты выхода на работу"><div className="day-top"><b>{date.getDate()}</b><span>—</span></div><span>До начала</span></button>;const shift=getShift(state,date),scheduled=getScheduledShift(state,date),vacation=state.vacations.some(p=>p.start<=dateKey&&dateKey<=p.end),sick=state.sickLeaves.some(p=>p.start<=dateKey&&dateKey<=p.end);const label=vacation?'Отпуск':sick?'Больничный':shiftLabel(shift);return <button className={`calendar-day ${shift} ${holiday?'holiday':''} ${today?'today':''} ${note?'has-note':''}`} data-shift={shift} onClick={()=>onEdit(dateKey)} title={holiday?holidayName(date):label}><div className="day-top"><b>{date.getDate()}</b><span>{holiday?'П':note?'З':''}</span></div><span>{label}</span>{scheduled!==shift&&<small>изменено</small>}</button>}

function PayView({state,calc,keyMonth,payment,setAdvance,goMonth,goYear}:{state:State;calc:ReturnType<typeof calcMonth>;keyMonth:string;payment:(field:'advanceDate'|'remainderDate',value:string)=>void;setAdvance:(value:string)=>void;goMonth:(n:number)=>void;goYear:(n:number)=>void}){const hasCustomAdvance=calc.advanceIsCustom;const annual=useMemo(()=>calcYear(state,calc.year),[state,calc.year]);return <section className="pay-page"><div className="pay-layout"><div className="pay-main"><div className="pay-hero"><div><span className="eyebrow">Расчёт за {MONTHS[calc.month]}</span><h2>{formatMoney(calc.net)}</h2><p>Ожидаемо на руки после НДФЛ</p></div><div className="gross-pill"><span>Начислено</span><b>{formatMoney(calc.gross)}</b></div></div><div className="breakdown-card"><SectionTitle eyebrow="Состав" title="Из чего складывается зарплата"/><div className="money-row"><span>Базовая часть</span><b>{formatMoney(calc.base)}</b></div><div className="money-row"><span>Доплата за дополнительные смены</span><b>{formatMoney(calc.extraPay)}</b></div><div className="money-row"><span>Праздничная доплата · {state.holidayCoeff}×</span><b>{formatMoney(calc.holidayExtra)}</b></div><div className="money-row"><span>Ночная доплата · {state.nightExtraPercent}%</span><b>{formatMoney(calc.nightExtra)}</b></div><div className="money-row"><span>Отпускные</span><b>{formatMoney(calc.vacPay)}</b></div><div className="money-row"><span>Больничные</span><b>{formatMoney(calc.sickPay)}</b></div><div className="money-row tax"><span>НДФЛ</span><b>− {formatMoney(calc.tax)}</b></div><div className="money-row total"><span>На руки</span><b>{formatMoney(calc.net)}</b></div></div></div><aside className="pay-side"><div className="pay-date-card"><SectionTitle eyebrow="Выплаты" title="Аванс и остаток" action={<div className="month-picker"><button onClick={()=>goMonth(-1)}>‹</button><b>{MONTHS[calc.month]} {calc.year}</b><button onClick={()=>goMonth(1)}>›</button></div>}/><div className="payment-explainer"><b>Аванс по умолчанию — 50% оклада</b><span>Если вы не меняли сумму, WorkerTink использует половину указанного оклада. Введите фактическую сумму, чтобы переопределить значение для этого месяца.</span></div><Field label="Сумма аванса, ₽" help={hasCustomAdvance?'Установлено вручную для этого месяца.':'Используется 50% указанного оклада. Измените поле, если фактический аванс отличается.'}><input type="number" min="0" step="1" value={hasCustomAdvance?state.advances[keyMonth]:calc.advance} onChange={e=>setAdvance(e.target.value)} onFocus={e=>{if(!hasCustomAdvance)e.currentTarget.select()}} /></Field><Field label="Дата зачисления аванса"><input type="date" value={calc.paymentDates.advanceDate} onChange={e=>payment('advanceDate',e.target.value)}/></Field><Field label="Дата зачисления остатка"><input type="date" value={calc.paymentDates.remainderDate} onChange={e=>payment('remainderDate',e.target.value)}/></Field><div className="payout-total"><div><span>Аванс{hasCustomAdvance?' · вручную':' · 50% оклада'}</span><b>{formatMoney(calc.advance)}</b><small>{calc.paymentDates.advanceDate||'дата не указана'}</small></div><div><span>Остаток</span><b>{formatMoney(calc.remainder)}</b><small>{calc.paymentDates.remainderDate||'дата не указана'}</small></div></div></div></aside></div><AnnualSummary annual={annual} goYear={goYear}/></section>}

function AnnualSummary({annual,goYear}:{annual:ReturnType<typeof calcYear>;goYear:(n:number)=>void}){return <section className="annual-card"><div className="annual-head"><div><span className="eyebrow">Годовой итог</span><h2>Доход за {annual.year}</h2><p>Все 12 месяцев с учётом смен, дополнительных смен, ночных и праздничных доплат, отпуска, больничных и НДФЛ.</p></div><div className="annual-year-controls"><button onClick={()=>goYear(-1)} aria-label="Предыдущий год">‹</button><strong>{annual.year}</strong><button onClick={()=>goYear(1)} aria-label="Следующий год">›</button></div></div><div className="annual-kpis"><div><span>На руки</span><b>{formatMoney(annual.net)}</b><small>итог за год</small></div><div><span>Начислено</span><b>{formatMoney(annual.gross)}</b><small>до НДФЛ</small></div><div><span>НДФЛ</span><b>{formatMoney(annual.tax)}</b><small>удержано</small></div><div><span>Среднее на руки</span><b>{formatMoney(annual.averageMonthlyNet)}</b><small>в месяц</small></div></div><div className="annual-components"><div><span>Базовая часть</span><b>{formatMoney(annual.base)}</b></div><div><span>Доп. смены</span><b>{formatMoney(annual.extraPay)}</b></div><div><span>Праздничные доплаты</span><b>{formatMoney(annual.holidayExtra)}</b></div><div><span>Ночные доплаты</span><b>{formatMoney(annual.nightExtra)}</b></div><div><span>Отпускные</span><b>{formatMoney(annual.vacPay)}</b></div><div><span>Больничные</span><b>{formatMoney(annual.sickPay)}</b></div><div><span>Смены</span><b>{annual.work}</b></div><div><span>Праздничные смены</span><b>{annual.holidayWork}</b></div><div><span>Дни отпуска</span><b>{annual.vacDays}</b></div><div><span>Дни больничного</span><b>{annual.sickDays}</b></div></div><div className="annual-table-wrap"><table className="annual-table"><thead><tr><th>Месяц</th><th>Начислено</th><th>НДФЛ</th><th>На руки</th><th>Аванс</th><th>Остаток</th></tr></thead><tbody>{annual.months.map((m)=><tr key={m.month}><td>{MONTHS[m.month]}</td><td>{formatMoney(m.gross)}</td><td>{formatMoney(m.tax)}</td><td><b>{formatMoney(m.net)}</b></td><td>{formatMoney(m.advance)}</td><td>{formatMoney(m.remainder)}</td></tr>)}</tbody><tfoot><tr><th>Итого</th><th>{formatMoney(annual.gross)}</th><th>{formatMoney(annual.tax)}</th><th>{formatMoney(annual.net)}</th><th>{formatMoney(annual.advance)}</th><th>{formatMoney(annual.remainder)}</th></tr></tfoot></table></div><p className="annual-footnote">Годовой итог считается по месяцам начисления. До даты выхода зарплата не начисляется. Аванс по умолчанию составляет 50% указанного оклада; его можно изменить отдельно для каждого месяца.</p></section>}

function AbsenceView({state,vac,sick,setVac,setSick,addPeriod,removePeriod}:{state:State;vac:PeriodDraft;sick:PeriodDraft;setVac:(v:PeriodDraft)=>void;setSick:(v:PeriodDraft)=>void;addPeriod:(k:'vacations'|'sickLeaves',d:PeriodDraft)=>void;removePeriod:(k:'vacations'|'sickLeaves',i:number)=>void}){const used=state.vacations.reduce((n,p)=>n+vacationCalendarDays(state,p),0);return <section className="absence-page"><div className="absence-overview"><div><span>Лимит отпуска</span><b>{state.vacTotal}</b><small>дней</small></div><div><span>Использовано</span><b>{used}</b><small>дней отпуска</small></div><div><span>Остаток</span><b>{Math.max(0,state.vacTotal-used)}</b><small>дней</small></div></div><div className="absence-grid"><PeriodEditor title="Отпуск" description="Праздничные дни внутри периода не уменьшают количество оплачиваемых дней отпуска." draft={vac} setDraft={setVac} kind="vacations" periods={state.vacations} addPeriod={addPeriod} removePeriod={removePeriod}/><PeriodEditor title="Больничный" description="Укажите фактический период больничного — он исключается из отработанных смен." draft={sick} setDraft={setSick} kind="sickLeaves" periods={state.sickLeaves} addPeriod={addPeriod} removePeriod={removePeriod}/></div></section>}
function PeriodEditor({title,description,draft,setDraft,kind,periods,addPeriod,removePeriod}:{title:string;description:string;draft:PeriodDraft;setDraft:(v:PeriodDraft)=>void;kind:'vacations'|'sickLeaves';periods:{start:string;end:string}[];addPeriod:(k:'vacations'|'sickLeaves',d:PeriodDraft)=>void;removePeriod:(k:'vacations'|'sickLeaves',i:number)=>void}){return <div className="period-editor"><SectionTitle eyebrow="Период" title={title}/><p className="hint">{description}</p><div className="period-items">{periods.length?periods.map((p,i)=><div className="period-item" key={`${p.start}-${p.end}-${i}`}><div><b>{p.start} → {p.end}</b><small>Период сохранён в профиле</small></div><button onClick={()=>removePeriod(kind,i)} aria-label="Удалить">×</button></div>):<div className="empty-state">Пока нет периодов</div>}</div><div className="period-add"><input type="date" value={draft.start} onChange={e=>setDraft({...draft,start:e.target.value})}/><span>→</span><input type="date" value={draft.end} onChange={e=>setDraft({...draft,end:e.target.value})}/><Button primary onClick={()=>addPeriod(kind,draft)}>Добавить</Button></div></div>}

