function SettingsView({state,patch,exportData,importData,importNotes,exportAllNotes,reopenSetup}:{state:State;patch:(p:Partial<State>)=>void;exportData:()=>void;importData:(f:File)=>void;importNotes:(f:File)=>void;exportAllNotes:()=>void;reopenSetup:()=>void}){return <section><div className="settings-intro"><span className="eyebrow">Профиль</span><h2>Настройки WorkerTink</h2><p>Изменения сохраняются автоматически. Расчёт зарплаты обновляется сразу после изменения параметров.</p></div><div className="settings-grid"><div className="settings-card"><SectionTitle eyebrow="Доход" title="Основные параметры"/><Field label="Оклад, ₽"><input type="number" min="0" value={state.salary} onChange={e=>patch({salary:Math.max(0,Number(e.target.value)||0)})}/></Field><Field label="НДФЛ, %"><input type="number" min="0" max="100" step="0.1" value={state.taxRate} onChange={e=>patch({taxRate:Math.min(100,Math.max(0,Number(e.target.value)||0))})}/></Field><Field label="Стаж, лет"><input type="number" min="0" max="60" value={state.stage} onChange={e=>patch({stage:Math.min(60,Math.max(0,Number(e.target.value)||0))})}/></Field><Field label="Отпуск, дней"><input type="number" min="0" value={state.vacTotal} onChange={e=>patch({vacTotal:Math.max(0,Number(e.target.value)||0)})}/></Field></div><div className="settings-card"><SectionTitle eyebrow="График" title="Сменная модель"/><Field label="Тип графика"><select value={state.scheduleType} onChange={e=>patch(applyScheduleType(state,e.target.value as State['scheduleType']))}>{scheduleTypeOptions.map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Дата начала"><input type="date" value={state.startDate} onChange={e=>patch({startDate:e.target.value})}/></Field>{state.scheduleType!=='2/2'&&<Field label={state.scheduleType==='7/0'?'Тип вахты':'Смена'}><select value={state.scheduleShift} onChange={e=>patch({scheduleShift:e.target.value as State['scheduleShift']})}><option value="day">День</option><option value="night">Ночь</option>{state.scheduleType==='7/0'&&<option value="full">Сутки</option>}</select></Field>}{state.scheduleType==='2/2'&&<Field label="Пара смен"><select value={state.schedulePairType} onChange={e=>patch({schedulePairType:e.target.value as State['schedulePairType']})}><option value="day-day">День / День</option><option value="day-night">День / Ночь</option><option value="night-night">Ночь / Ночь</option></select></Field>}{state.scheduleType==='7/0'&&<Field label="Вахта, месяцев" help="Непрерывный период работы. После окончания выбранной длительности календарь показывает выходной период до новой даты старта."><input type="number" min="1" max="6" value={state.scheduleVakhtaMonths} onChange={e=>patch({scheduleVakhtaMonths:Math.min(6,Math.max(1,Number(e.target.value)||1))})}/></Field>}<Field label="Коэффициент праздника" help="Повышение применяется только к фактически отработанным праздничным сменам."><input type="number" min="1" max="10" step="0.1" value={state.holidayCoeff} onChange={e=>patch({holidayCoeff:Math.min(10,Math.max(1,Number(e.target.value)||1))})}/></Field><Field label="Ночная доплата, %" help="Доплата за ночные часы. По умолчанию 20%; фактический размер зависит от условий работодателя."><input type="number" min="0" max="200" step="1" value={state.nightExtraPercent} onChange={e=>patch({nightExtraPercent:Math.min(200,Math.max(0,Number(e.target.value)||0))})}/></Field></div><div className="settings-card full-width"><SectionTitle eyebrow="Средний заработок" title="История доходов"/><p className="hint">Доходы нужны для более точного расчёта отпускных и больничных. Пустые месяцы не добавляются в среднее.</p><div className="income-grid">{Array.from({length:24},(_,i)=>{const d=new Date(new Date().getFullYear(),new Date().getMonth()-i-1,1),k=monthKey(d.getFullYear(),d.getMonth());return <label key={k}><span>{MONTHS[d.getMonth()]} {d.getFullYear()}</span><input type="number" min="0" value={state.incomeHistory[k]??''} placeholder="Доход" onChange={e=>{const x={...state.incomeHistory};if(e.target.value==='')delete x[k];else x[k]=Math.max(0,Number(e.target.value)||0);patch({incomeHistory:x})}}/></label>})}</div></div><div className="settings-card"><SectionTitle eyebrow="Данные" title="Профиль"/><div className="data-buttons"><Button primary onClick={exportData}>Экспорт JSON</Button><label className="btn file-btn">Импорт JSON<input type="file" accept="application/json" onChange={e=>e.target.files?.[0]&&importData(e.target.files[0])}/></label></div><Button quiet className="setup-reset" onClick={reopenSetup}>Открыть мастер настройки</Button></div><div className="settings-card"><SectionTitle eyebrow="Заметки смен" title="Визуальный редактор"/><p className="hint">Заметка редактируется визуально, а Markdown используется как переносимый формат хранения и экспорта. Импорт понимает файлы WorkerTink с заголовками <code>## SHIFT: ДАТА</code>.</p><div className="data-buttons"><Button primary onClick={exportAllNotes}>Экспорт заметок .md</Button><label className="btn file-btn">Импорт заметок .md<input type="file" accept=".md,text/markdown,text/plain" onChange={e=>e.target.files?.[0]&&importNotes(e.target.files[0])}/></label></div></div><div className="settings-card"><SectionTitle eyebrow="Внешний вид" title="Тема"/><Field label="Тема"><select value={state.theme} onChange={e=>patch({theme:e.target.value as State['theme']})}><option value="auto">Системная</option><option value="light">Светлая</option><option value="dark">Тёмная</option></select></Field></div></div></section>}
